DocumentManagement = {
    init: async function (app, container) {
        app = app || session.app;
        app = await api.get("ContentManagement/App(" + app.Id + ")");
        container = container || $(".component[name=DocumentManagement]");

        DocumentManagement.addMeta();
        DocumentManagement.initSplitter(container);
        DocumentManagement.folderTypeInfo = await api.getType("DocumentManagement/Folder");

        var treeElement = $("[name=treeRoot]", container);
        var listingContainer = $(".component[name=FolderManagement]", container);
        var tree = await DocumentManagement.initTree(app, treeElement, listingContainer);

        DocumentManagement.disableTreeContextMenu(treeElement);
    },

    addMeta: function () {
        api.addToMetaCache([{
            Name: "DocumentManagement",
            Types: [[meta[DocumentManagement/Folder]]]
        }]);
    },

    initSplitter: function (container) {
        var splitter = $("[name=splitter]", container);
        var existing = splitter.data("kendoSplitter");

        if (existing) {
            existing.destroy();
        }

        splitter.kendoSplitter({
            scrollable: false,
            panes: [
                {
                    collapsible: false,
                    resizable: false,
                    size: "320px",
                    min: "280px",
                    max: "360px"
                },
                {
                    collapsible: false,
                    resizable: false,
                    scrollable: false
                }
            ]
        });
    },

    initTree: async function (app, treeElement, listingContainer) {
        var dataSource = await DocumentManagement.getDataForFoldersTree(app);
        var tree = new DataTreeViewWidget(treeElement, {
            dataSource: dataSource,
            template: DocumentManagement.folderTreeTemplate(),
            dragAndDrop: true
        });

        tree.onSelect = function (event) {
            return DocumentManagement.selectNode(event, tree, app, listingContainer);
        };

        tree.init();

        DocumentManagement.bindTreeActionButtons(tree, app, listingContainer);
        DocumentManagement.bindFolderDragDrop(tree, app, listingContainer);
        DocumentManagement.bindFileDropToTree(tree, app, listingContainer);
        await DocumentManagement.loadInitialFolder(app, tree, dataSource, listingContainer);

        return tree;
    },

    loadInitialFolder: async function (app, tree, dataSource, listingContainer) {
        var firstFolder = dataSource && dataSource.length ? dataSource[0] : null;

        if (!firstFolder) {
            return;
        }

        await FolderManagement.init(app, listingContainer, firstFolder.folder, false);
        DocumentManagement.selectTreeNode(tree, firstFolder);
    },

    folderTreeTemplate: function () {
        return [
            '<span class="document-tree-node">',
                '<span class="document-tree-node-main">',
                    '<span class="document-tree-node-icon" aria-hidden="true"></span>',
                    '<span class="document-tree-node-text mx-1">#: item.text #</span>',
                '</span>',

                '<span class="document-tree-actions">',
                    '<button type="button" class="document-tree-action" name="downloadFolder" title="[resource_displayname[download]]">',
                        '<span class="k-icon k-i-download"></span>',
                    '</button>',
                    '<button type="button" class="document-tree-action document-tree-action-danger" name="deleteFolder" title="[resource_displayname[delete]]">',
                        '<span class="k-icon k-i-trash"></span>',
                    '</button>',
                '</span>',
            '</span>'
        ].join("");
    },

    getDataForFoldersTree: async function (app) {
        var folders = (
            await api.get(
                "DocumentManagement/Folder?$filter=AppId eq " +
                app.Id +
                "&$orderby=Name asc&_=" +
                Date.now()
            )
        ).value || [];

        return DocumentManagement.buildTreeDataSource(DocumentManagement.linkFoldersToParents(folders));
    },

    linkFoldersToParents: function (folders) {
        var rootFolders = folders.filter(function (folder) {
            return folder.ParentId == null;
        });

        for (var i = 0; i < rootFolders.length; i++) {
            DocumentManagement.linkChildFolders(rootFolders[i], folders);
        }

        return rootFolders;
    },

    linkChildFolders: function (folder, folders) {
        folder.SubFolders = folders.filter(function (child) {
            return child.ParentId == folder.Id;
        });

        for (var i = 0; i < folder.SubFolders.length; i++) {
            DocumentManagement.linkChildFolders(folder.SubFolders[i], folders);
        }
    },

    buildTreeDataSource: function (folders) {
        return folders.map(function (folder) {
            return {
                id: folder.Id,
                text: folder.Name,
                items: DocumentManagement.buildTreeDataSource(folder.SubFolders || []),
                path: folder.Path,
                parentId: folder.ParentId,
                folder: folder,
                expanded: folder.ParentId == null
            };
        });
    },

    selectNode: async function (event, tree, app, listingContainer) {
        if (!event || !event.node) {
            return;
        }

        var node = tree.kendoObject.dataItem(event.node);

        if (!node || !node.folder) {
            return;
        }

        DocumentManagement.highlightSelectedPath(tree, event.node);
        DocumentManagement.updateTreeFolderIcons(tree);

        if ($("[name=folderManagementShell]", listingContainer).length) {
            await FolderManagement.reloadFolderView(app, node.folder, false, false);
        } else {
            await FolderManagement.init(app, listingContainer, node.folder, false);
        }
    },

    selectTreeNode: function (tree, folderNode) {
        var node =
            folderNode.uid && tree.kendoObject.findByUid
                ? tree.kendoObject.findByUid(folderNode.uid)
                : null;

        if ((!node || !node.length) && tree.kendoObject.findByText) {
            node = tree.kendoObject.findByText(folderNode.text);
        }

        if (!node || !node.length) {
            return;
        }

        tree.kendoObject.select(node);
        DocumentManagement.highlightSelectedPath(tree, node);
        DocumentManagement.updateTreeFolderIcons(tree);
    },

    highlightSelectedPath: function (tree, node) {
        var treeElement = DocumentManagement.getTreeElement(tree);

        $(".document-tree-parent-selected", treeElement)
            .removeClass("document-tree-parent-selected");

        $(node)
            .parents("li.k-treeview-item")
            .children(".k-treeview-top, .k-treeview-mid, .k-treeview-bot, .k-in, .k-treeview-leaf")
            .addClass("document-tree-parent-selected");
    },

    getTreeElement: function (tree) {
        return tree.treeElement || tree.element || tree.kendoObject.element;
    },

    reloadFolderTree: async function (app, tree, folderId) {
        tree.kendoObject.setDataSource(await DocumentManagement.getDataForFoldersTree(app));

        if (folderId) {
            tree.kendoObject.expandTo(folderId);
        }
    },

    bindFolderDragDrop: function (tree, app, listingContainer) {
        if (!tree || !tree.kendoObject) {
            return;
        }

        tree.kendoObject.unbind("drop");
        tree.kendoObject.bind("drop", async function (event) {
            await DocumentManagement.dropFolder(event, tree, app, listingContainer);
        });
    },

    dropFolder: async function (event, tree, app, listingContainer) {
        var source = tree.kendoObject.dataItem(event.sourceNode);
        var destination = tree.kendoObject.dataItem(event.destinationNode);

        if (!DocumentManagement.isValidFolderDrop(event, source, destination)) {
            return;
        }

        var newParent = DocumentManagement.getDropParent(tree, event, destination);
        var newParentFolder = newParent && newParent.folder
            ? newParent.folder
            : null;

        var newParentId = newParentFolder
            ? newParentFolder.Id
            : null;

        if (source.folder.ParentId === newParentId) {
            return;
        }

        try {
            var movedFolder = null;

            await FolderManagement.loadFolderActions(
                $("[name=folderManagementShell]", listingContainer),
                app,
                async function (actions) {
                    movedFolder = await actions.moveFolder(source.folder, newParentFolder);
                }
            );

            movedFolder = movedFolder || await api.get("DocumentManagement/Folder(" + source.folder.Id + ")");

            await DocumentManagement.reloadFolderTree(app, tree, source.folder.Id);
            await FolderManagement.reloadFolderView(app, movedFolder, false, false);

            FolderManagement.selectFolderInTree(movedFolder);
        } catch (err) {
            error(err);
        }
    },

    isValidFolderDrop: function (event, source, destination) {
        if (!source || !source.folder || !destination || !destination.folder) {
            return DocumentManagement.rejectDrop(event);
        }

        if (source.id === destination.id) {
            return DocumentManagement.rejectDrop(event);
        }

        if (DocumentManagement.isDescendantOf(source, destination.id)) {
            DocumentManagement.rejectDrop(event);
            error("[resource_displayname[cannotmovefolderintoitself]]");
            return false;
        }

        return true;
    },

    rejectDrop: function (event) {
        if (event && event.setValid) {
            event.setValid(false);
        }

        return false;
    },

    getDropParent: function (tree, event, destination) {
        if (event.dropPosition === "over") {
            return destination;
        }

        var parentNode = $(event.destinationNode)
            .parents("li.k-treeview-item")
            .first();

        if (!parentNode.length) {
            return null;
        }

        return tree.kendoObject.dataItem(parentNode);
    },

    isDescendantOf: function (node, possibleParentId) {
        if (!node.items || !node.items.length) {
            return false;
        }

        for (var i = 0; i < node.items.length; i++) {
            if (node.items[i].id === possibleParentId) {
                return true;
            }

            if (DocumentManagement.isDescendantOf(node.items[i], possibleParentId)) {
                return true;
            }
        }

        return false;
    },
    bindFileDropToTree: function (tree, app, listingContainer) {
        var treeElement = DocumentManagement.getTreeElement(tree);

        treeElement
            .off("dragover.fileMove dragenter.fileMove dragleave.fileMove drop.fileMove")
            .on("dragover.fileMove dragenter.fileMove", "li.k-treeview-item", function (event) {
                DocumentManagement.handleFileDragOver(event, treeElement);
            })
            .on("dragleave.fileMove", "li.k-treeview-item", function () {
                DocumentManagement.clearTreeDropTarget($(this));
            })
            .on("drop.fileMove", "li.k-treeview-item", async function (event) {
                await DocumentManagement.dropFilesOnTreeNode( event, tree, app, listingContainer, treeElement, $(this));
            });
    },

    handleFileDragOver: function (event) {
        if (!DocumentManagement.isFileMoveDrag(event.originalEvent)) {
            return;
        }

        event.preventDefault();
        event.stopPropagation();

        event.originalEvent.dataTransfer.dropEffect = "move";
        DocumentManagement.markTreeDropTarget($(event.currentTarget));
    },

    markTreeDropTarget: function (node) {
        node.children(".k-treeview-top, .k-treeview-mid, .k-treeview-bot, .k-in, .k-treeview-leaf")
            .addClass("document-tree-drop-target");
    },

    clearTreeDropTarget: function (node) {
        node.children(".k-treeview-top, .k-treeview-mid, .k-treeview-bot, .k-in, .k-treeview-leaf")
            .removeClass("document-tree-drop-target");
    },

    clearAllTreeDropTargets: function (treeElement) {
        $(".document-tree-drop-target", treeElement)
            .removeClass("document-tree-drop-target");
    },

    dropFilesOnTreeNode: async function (event, tree, app, listingContainer, treeElement, targetNode) {
        if (!DocumentManagement.isFileMoveDrag(event.originalEvent)) {
            return;
        }

        event.preventDefault();
        event.stopPropagation();

        DocumentManagement.clearAllTreeDropTargets(treeElement);

        var destination = tree.kendoObject.dataItem(targetNode);
        var payload = DocumentManagement.getFileMovePayload(event.originalEvent);

        if (!destination || !destination.folder || !payload.files.length) {
            return;
        }

        await DocumentManagement.moveDroppedFilesToFolder(app,listingContainer,payload.files,destination.folder);
    },

    isFileMoveDrag: function (event) {
        if (!event || !event.dataTransfer || !event.dataTransfer.types) {
            return false;
        }

        return Array.prototype.indexOf.call(
            event.dataTransfer.types,
            "application/x-dms-files"
        ) >= 0;
    },

    getFileMovePayload: function (event) {
        try {
            return JSON.parse(
                event.dataTransfer.getData("application/x-dms-files")
            ) || { files: [] };
        } catch (err) {
            return { files: [] };
        }
    },

    moveDroppedFilesToFolder: async function (app, listingContainer, files, destinationFolder) {
        await FolderManagement.loadFileActions(
            $("[name=folderManagementShell]", listingContainer),
            app,
            async function (actions) {
                await actions.moveFilesToFolder(files, destinationFolder);
            }
        );

        await FolderManagement.reloadFolderView(app, destinationFolder, false, false);

        FolderManagement.selectFolderInTree(destinationFolder);
    },

    disableTreeContextMenu: function (treeElement) {
        treeElement
            .off("contextmenu.documentManagement")
            .on("contextmenu.documentManagement", function (event) {
                event.preventDefault();
            });
    },

    bindTreeActionButtons: function (tree, app, listingContainer) {
        var treeElement = DocumentManagement.getTreeElement(tree);

        treeElement
            .off("mousedown.documentTreeActions click.documentTreeActions")
            .on("mousedown.documentTreeActions", ".document-tree-action", function (event) {
                event.preventDefault();
                event.stopPropagation();
            })
            .on("click.documentTreeActions", ".document-tree-action", async function (event) {
                event.preventDefault();
                event.stopPropagation();

                var button = $(this);
                var node = button.closest("li");
                var nodeData = tree.kendoObject.dataItem(node);

                if (!nodeData || !nodeData.folder) {
                    return;
                }

                if (button.attr("name") === "downloadFolder") {
                    await DocumentManagement.handleDownloadFolder(app, listingContainer, nodeData.folder);
                    return;
                }

                if (button.attr("name") === "deleteFolder") {
                    await DocumentManagement.handleDeleteFolder(app, listingContainer, nodeData.folder);
                }
            });
    },

    handleDownloadFolder: async function (app, listingContainer, folder) {
        await FolderManagement.loadFolderActions(
            $("[name=folderManagementShell]", listingContainer),
            app,
            function (actions) {
                actions.downloadFolder(folder);
            }
        );
    },

    handleDeleteFolder: async function (app, listingContainer, folder) {
        await FolderManagement.loadFolderActions(
            $("[name=folderManagementShell]", listingContainer),
            app,
            function (actions) {
                actions.deleteFolder(null, folder, function () {
                    return DocumentManagement.init(app, $(".component[name=DocumentManagement]"));
                });
            }
        );
    },
    
    updateTreeFolderIcons: function (tree) {
        var treeElement = DocumentManagement.getTreeElement(tree);
        $(".document-tree-node-icon", treeElement)
            .attr("aria-hidden", "true");
    },

    refreshTreeAfterFolderChange: async function (app, folderId) {
        var treeElement = $(".component[name=DocumentManagement] [name=treeRoot]");
        var kendoTree = treeElement.data("kendoTreeView");

        if (!kendoTree) {
            return;
        }

        kendoTree.setDataSource(
            await DocumentManagement.getDataForFoldersTree(app)
        );

        if (folderId) {
            kendoTree.expandTo(folderId);
        }
    },
};
